const CITEKEY = /^[a-z][a-z0-9-]*[0-9]{4}[a-z0-9-]*$/u;

const HEADER = [
  "% Generated by @red-cup-engineering/bibliography-engineering-services-section. Do not edit by hand.",
  "% Source of truth: frontmatter `references:` maps and depth-2 bibliography carriers.",
  "",
].join("\n");

const DIRECT_FIELD_ORDER = Object.freeze(["author", "title", "year", "journal", "publisher", "eprint", "eprinttype", "doi", "url", "note"]);

function splitName(author) {
  const value = author.trim();
  if (value.includes(",")) return value;
  const parts = value.split(/\s+/u);
  if (parts.length <= 1) return value;
  return `${parts.at(-1)}, ${parts.slice(0, -1).join(" ")}`;
}
function joinAuthors(authors) {
  return authors.map(splitName).join(" and ");
}
function bibtexField(name, value) {
  return `  ${name} = {${value}},\n`;
}
function entryType(entry) {
  const type = entry.referenceType ?? entry.reference?.["reference-type"];
  return typeof type === "string" && type.trim() !== "" ? type.trim().toLowerCase() : "misc";
}

/**
 * Render one reconciled citekey entry as a BibTeX entry string.
 *
 * @param {{citekey: string, referenceType?: string, authors: string[], title: string, year: number, publication?: string, publisher?: string, translator?: string, eprint?: string, eprinttype?: string, doi?: string, url?: string, note?: string}} entry
 * @returns {string} the rendered `@type{key, ...}` entry, newline-terminated.
 */
export function renderBibtexEntry(entry) {
  const fields = {
    author: entry.authors?.length ? joinAuthors(entry.authors) : undefined,
    title: entry.title,
    year: entry.year,
    journal: entry.publication,
    publisher: entry.publisher,
    eprint: entry.eprint,
    eprinttype: entry.eprinttype ?? (entry.eprint !== undefined ? "arxiv" : undefined),
    doi: entry.doi,
    url: entry.url,
    note: entry.translator !== undefined ? `trans. ${entry.translator}${entry.note !== undefined ? `; ${entry.note}` : ""}` : entry.note,
  };
  const lines = [`@${entryType(entry)}{${entry.citekey},\n`];
  for (const name of DIRECT_FIELD_ORDER) {
    const value = fields[name];
    if (value === undefined || value === null || String(value).trim() === "") continue;
    lines.push(bibtexField(name, String(value).trim()));
  }
  if (lines.length > 1 && lines.at(-1).endsWith(",\n")) lines[lines.length - 1] = `${lines.at(-1).slice(0, -2)}\n`;
  lines.push("}\n");
  return lines.join("");
}

/**
 * Project the reconciled citekey set into deterministic BibTeX text: sorted
 * entries, explicit field order, byte-identical output for unchanged input.
 *
 * @param {{triples: Array<{citekey: string, reference: object, path: string}>, carriers: Array<{citekey: (string|null), path: string, recognized: object}>}} collected
 * @returns {string} the generated `.bib` text, header-commented as a build artifact.
 */
export function projectBibtex({ triples, carriers }) {
  const byKey = new Map();
  for (const { citekey, reference } of triples) {
    if (!CITEKEY.test(citekey) || byKey.has(citekey)) continue;
    byKey.set(citekey, { citekey, ...reference });
  }
  for (const carrier of carriers) {
    const key = typeof carrier.recognized?.key === "string" && CITEKEY.test(carrier.recognized.key)
      ? carrier.recognized.key
      : (CITEKEY.test(carrier.path.split("/").pop().replace(/\.md$/u, "")) ? carrier.path.split("/").pop().replace(/\.md$/u, "") : null);
    if (key === null) continue;
    const { authors, year, title } = carrier.recognized;
    if (!Array.isArray(authors) || authors.length === 0 || !Number.isInteger(year) || typeof title !== "string" || title.trim() === "") continue;
    byKey.set(key, { citekey: key, authors, year, title, referenceType: carrier.recognized.referenceType });
  }
  const keys = [...byKey.keys()].sort();
  const body = keys.map((key) => renderBibtexEntry(byKey.get(key))).join("\n");
  return `${HEADER}${body}`;
}
